styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='SmallX',fontName='Helvetica',fontSize=7,leading=9)); styles.add(ParagraphStyle(name='BodyX',fontName='Helvetica',fontSize=10,leading=14,spaceAfter=7)); styles.add(ParagraphStyle(name='CoverX',fontName='Helvetica-Bold',fontSize=26,leading=31,textColor=colors.HexColor('#12354b'),spaceAfter=22))
class Builder:
 def __init__(self,name,title,subtitle,wide=False):
  self.name=name; self.wide=wide; self.doc=Document(); self.story=[]
  sec=self.doc.sections[0]; sec.page_width=Cm(29.7 if wide else 21); sec.page_height=Cm(21 if wide else 29.7); sec.top_margin=sec.bottom_margin=Cm(1.6); sec.left_margin=sec.right_margin=Cm(1.5)
  normal=self.doc.styles['Normal']; normal.font.name='Calibri'; normal.font.size=Pt(10)
  normal.paragraph_format.space_after=Pt(6)
  foot=sec.footer.paragraphs[0]; foot.text='NAC Kwilu | 2027–2028 | Version de travail à valider · '
  fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); foot._p.append(fld)
  self.doc.add_heading(title,0); self.story.append(Paragraph(escape(title),styles['CoverX']))
  self.p(subtitle); self.p('Consortium SANRU–ICHESS–FONLIV–FDSS | Chef de file : SANRU')
  self.p('Province du Kwilu, République démocratique du Congo\nPériode : 1er janvier 2027 – 31 décembre 2028\nÉdition : 6 novembre 2026 | Statut : proposition technique pour validation')
  self.p('Source principale : '+SOURCE+' — DP n° ZR-DRC-MSP-235334-CS-QCBS.')
  self.p('Les cibles proposées ne sont pas des engagements contractuels approuvés. Les données anciennes du TECH-4 ne constituent pas des références 2027. Validation conjointe requise au plus tard le 31 mars 2027.')
  self.page()
 def p(self,text):
  self.doc.add_paragraph(text); self.story.append(Paragraph(escape(text).replace('\n','<br/>'),styles['BodyX']))
 def h(self,text,level=1):
  self.doc.add_heading(text,level); self.story.append(Paragraph(escape(text),styles['Heading1' if level==1 else 'Heading2']))
 def page(self): self.doc.add_page_break(); self.story.append(PageBreak())
 def table(self,headers,rows,widths=None):
  t=self.doc.add_table(rows=1,cols=len(headers)); t.style='Light Shading Accent 1'
  for c,x in zip(t.rows[0].cells,headers): c.text=str(x)
  trpr=t.rows[0]._tr.get_or_add_trPr(); rep=OxmlElement('w:tblHeader'); trpr.append(rep)
  for row in rows:
   cells=t.add_row().cells
   for c,x in zip(cells,row):
    c.text=str(x)
    for p in c.paragraphs:
     for r in p.runs:r.font.size=Pt(8 if self.wide else 9)
  pagew=(landscape(A4) if self.wide else A4)[0]-85
  if widths: widths=[pagew*x/sum(widths) for x in widths]
  else: widths=[pagew/len(headers)]*len(headers)
  data=[[Paragraph(escape(str(x)).replace('\n','<br/>'),styles['SmallX']) for x in row] for row in [headers]+rows]
  tb=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');tb.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#d9e8ef')),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#b9c5ce')),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]));self.story.extend([tb,Spacer(1,10)])
 def save(self):
  self.doc.save(OUT/(self.name+'.docx'))
  def footer(c,d):
   c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#546575'));c.drawString(42,24,'NAC Kwilu | 2027–2028 | Proposition à valider');c.drawRightString(d.pagesize[0]-42,24,str(d.page))
  pdf=SimpleDocTemplate(str(OUT/(self.name+'.pdf')),pagesize=landscape(A4) if self.wide else A4,rightMargin=42,leftMargin=42,topMargin=40,bottomMargin=42,title=self.name,author='Consortium SANRU – document technique de travail')
  pdf.build(self.story,onFirstPage=footer,onLaterPages=footer)

p=Builder('Plan_suivi_evaluation_NAC_Kwilu_2027_2028','PLAN DE SUIVI-ÉVALUATION','Nutrition à assise communautaire • Redevabilité • Apprentissage')
p.h('Guide de lecture et validation')
p.p('Ce plan organise le suivi des quatre objectifs du TECH-4 sur 24 mois. Il est accompagné d’un cadre de performance autonome, aux formats Word et PDF, qui contient les définitions et fiches des 26 indicateurs. Les deux documents doivent être approuvés ensemble. Les activités initialement décrites dans un contexte 2021–2022 sont reprogrammées, sans présumer de la continuité des financements ou des personnels cités.')
p.table(['Rubrique','Contenu'],[['1–3','Périmètre, réserves et logique des résultats'],['4–7','Gouvernance, information, qualité et indicateurs'],['8–11','Évaluations, surveillance, redevabilité et apprentissage'],['12–15','Calendrier, budget, risques et outils de gestion']],[1,3])
p.table(['Visa requis','Responsabilité de validation'],[['SANRU / consortium','Faisabilité opérationnelle et financière ; répartition des tâches'],['DPS Kwilu / PRONANUT','Normes techniques, répertoires, intégration SNIS et SNSAP'],['ECZS des 10 ZS','Dénominateurs, déploiement, circuits de remontée'],['UG-PDSS / autorité contractante, selon mandat actualisé','Alignement contractuel ; calendrier et cibles'],['Protection des données / éthique','Sécurité, consentement et protocoles de recherche']],[1,3])
p.h('1. Périmètre et diagnostic documentaire')
p.p('Le TECH-4 vise l’amélioration de l’accès, de l’utilisation et de la qualité des services de nutrition et de santé communautaires, avec un volet VBG et un renforcement du système de santé. Le suivi couvre les enfants de moins de cinq ans, particulièrement les moins de deux ans, les femmes enceintes et allaitantes, les ménages et les structures communautaires et sanitaires. Les adolescents et les groupes vulnérables sont inclus dans les activités pertinentes de prévention et de protection.')
p.p('Zones de santé citées : Djuma, Kingandu, Moanza, Kimputu, Sia, Pay-Kongila, Yasa Bonga, Mosango, Gungu et Kikwit Nord. Les variantes Yassa/Bonga Yassa et Pay Kongila devront être harmonisées avec les codes officiels de la DPS.')
p.table(['Élément du TECH-4','Traitement pour 2027–2028'],[['10 ZS ; 250 AS ; 190 SSC ; 423 FOSA','Périmètre de planification à confirmer par répertoire géocodé à M3 ; distinguer AS, FOSA, SSC et CAC.'],['3 188 CAC ; passage mentionnant 2 250/2 188 et 71 %','Incohérence arithmétique et de dénominateur : ne pas reprendre comme couverture initiale ; inventorier villages et CAC actives/inactives.'],['415 695 ménages ; 8 314 RECO estimés ; 4 956 prioritaires + 3 358 restants','Effectifs historiques non actualisés ; 4 956 constitue le volume prioritaire repris pour la planification de formation, non un effectif déjà disponible.'],['47 % de retard de croissance ; AME 32,7 % ; diversité 27,1 %','Repères historiques uniquement. Vérifier année, population et définition ; réaliser une référence initiale comparable.'],['Données 2021–2022, primes et montants historiques','Pas d’extrapolation en coûts 2027 ; vérifier ressources, normes, partenaires et conditions contractuelles.']],[2,4])
p.h('2. Finalité, questions et principes du suivi-évaluation')
p.p('Finalité : produire des informations fiables et utilisables pour piloter l’équité de couverture, la qualité, la sécurité et la pérennité des services. Le dispositif doit rester proportionné aux capacités locales et alimenter le SNIS plutôt que créer une chaîne parallèle.')
for x in ['Les services atteignent-ils les enfants et ménages attendus, y compris les plus éloignés et ceux en situation de handicap ?','Les prestataires sont-ils compétents, équipés et soutenus ? Les références nutritionnelles aboutissent-elles ?','Les pratiques ANJE et d’hygiène évoluent-elles, et quels facteurs expliquent les changements ou leur absence ?','La participation communautaire, la prévention des VBG et les mécanismes de recours fonctionnent-ils sans exposer les personnes ?','Les données sont-elles exactes, ponctuelles et utilisées pour lever les goulots d’étranglement ? Quels acquis peuvent être maintenus après décembre 2028 ?']:p.p('• '+x)
p.h('3. Théorie du changement et chaîne de résultats')
p.p('Si le consortium et la DPS rendent disponibles des RECO compétents, des intrants, des structures communautaires actives, des soins de qualité et des circuits de protection sûrs, et si les ménages participent aux décisions et reçoivent des conseils adaptés, alors l’accès, l’utilisation continue et la qualité des services progresseront. Les pratiques alimentaires et d’hygiène pourront s’améliorer et contribuer à une meilleure situation nutritionnelle. Cette contribution dépend aussi de la sécurité alimentaire, des revenus, des épidémies et de l’accès à l’eau ; elle ne prouve pas une attribution causale au seul projet.')
